/**
 * 総合全銘柄・全市場アセットユニバース
 * 
 * 東証全上場銘柄 (プライム・スタンダード・グロース・ETF・REIT等 4,400+銘柄)
 * 米国主要大型・成長株 (S&P 500, NASDAQ 100等 80+銘柄)
 * 主要市場指数・為替・コモディティ・暗号資産
 *
 * クライアントサイドでの完全インメモリ即時検索を可能にし、
 * タイピング毎のサーバーAPI呼び出しをゼロ（0負荷・0ミリ秒遅延）に抑えます。
 */

