const popularTickerSet = new Set(
  Array.isArray(POPULAR_STOCKS) ? POPULAR_STOCKS.map((p) => p.ticker.toUpperCase()) : []
);

export const ALL_UNIVERSE_STOCKS: UniverseStock[] = RAW_UNIVERSE.map((row) => {
  const tickerUpper = row[0].toUpperCase();
  return {
    ticker: row[0],
    name: row[1],
    market: row[2],
    sector: row[3],
    aliases: row[4],
    normName: normalizeSearchQuery(row[1]),
    normAliases: row[4] ? normalizeSearchQuery(row[4]) : undefined,
    tickerUpper,
    nameLower: row[1].toLowerCase(),
    sectorLower: row[3] ? row[3].toLowerCase() : "",
    rawAliasesLower: row[4] ? row[4].toLowerCase() : "",
    isPopular: popularTickerSet.has(tickerUpper),
  };
});

/**
 * Search-query normalizer. The implementation moved to `src/lib/searchNormalize`
 * (PERF-01) and is re-exported here so existing imports and tests keep working.
 */
export { normalizeSearchQuery };

/**
 * Ultra-fast in-memory client-side stock search across 4,500+ instruments.
 * Supports multi-token AND search, NFKC normalization (half-width kana, full-width alphanum),
 * and relevance priority scoring (popular large-cap stocks boosted).
 */
export function searchStockUniverse(
  query: string,
  options?: {
    limit?: number;
    market?: StockMarket | "ALL";
    sector?: string;
  },
): UniverseStock[] {
  const norm = normalizeSearchQuery(query);
  const limit = options?.limit ?? 20;
  const targetMarket = options?.market;
  const targetSector = options?.sector;

  if (!norm) {
    let pool = ALL_UNIVERSE_STOCKS;
    if (targetMarket && targetMarket !== "ALL") {
      pool = pool.filter((s) => s.market === targetMarket);
    }
    if (targetSector) {
      pool = pool.filter((s) => s.sector === targetSector);
    }
    return pool.slice(0, limit);
  }

  const tokens = norm.split(/\s+/).filter(Boolean);
  const tokenTuples =
    tokens.length > 1
      ? tokens.map((tok) => ({
          tok,
          tokUpper: tok.toUpperCase(),
        }))
      : [];
  const normUpper = norm.toUpperCase();
  const rawUpper = query.trim().toUpperCase();
  const rawLower = query.trim().toLowerCase();

  const scoredMatches: { stock: UniverseStock; score: number }[] = [];

  for (let i = 0; i < ALL_UNIVERSE_STOCKS.length; i++) {
    const s = ALL_UNIVERSE_STOCKS[i];
    if (targetMarket && targetMarket !== "ALL" && s.market !== targetMarket) {
      continue;
    }
    if (targetSector && s.sector !== targetSector) {
      continue;
    }

    const tUpper = s.tickerUpper || s.ticker.toUpperCase();
    const nNorm = s.nameLower || s.name.toLowerCase();
    const normName = s.normName || "";
    const normAliases = s.normAliases || "";
    const rawAliases = s.rawAliasesLower || "";
    const sSector = s.sectorLower || "";
    const isPopular = s.isPopular ?? false;

    // Multi-token (AND search) mode
    if (tokenTuples.length > 1) {
      let allMatch = true;
      let tokenScore = 0;

      for (let j = 0; j < tokenTuples.length; j++) {
        const { tok, tokUpper } = tokenTuples[j];
        const matchTicker = tUpper.includes(tokUpper);
        const matchName = normName.includes(tok) || nNorm.includes(tok);
        const matchAlias = normAliases.includes(tok) || rawAliases.includes(tok);
        const matchSector = sSector.includes(tok);

        if (!matchTicker && !matchName && !matchAlias && !matchSector) {
          allMatch = false;
          break;
        }

        if (tUpper === tokUpper) tokenScore += 500;
        else if (tUpper.startsWith(tokUpper)) tokenScore += 250;
        else if (normName.startsWith(tok)) tokenScore += 200;
        else if (normName.includes(tok)) tokenScore += 100;
        else if (matchAlias) tokenScore += 80;
        else if (matchSector) tokenScore += 50;
      }

      if (allMatch) {
        if (isPopular) tokenScore += 300;
        scoredMatches.push({ stock: s, score: tokenScore });
      }
      continue;
    }

    // Single token mode with rich hierarchical scoring
    let score = 0;
    if (isPopular) score += 200;

    // 1. Exact ticker match (e.g. "7203", "AAPL", "７２０３")
    if (tUpper === normUpper || tUpper === rawUpper) {
      score += 2000;
      scoredMatches.push({ stock: s, score });
      continue;
    }

    // 2. Exact name match
    if (normName === norm || nNorm === norm || nNorm === rawLower) {
      score += 1500;
      scoredMatches.push({ stock: s, score });
      continue;
    }

    // 3. Ticker prefix match (e.g. "720" -> "7203", "AA" -> "AAPL")
    if (tUpper.startsWith(normUpper) || tUpper.startsWith(rawUpper)) {
      score += 800;
    }

    // 4. Name prefix match
    if (normName.startsWith(norm) || nNorm.startsWith(norm) || nNorm.startsWith(rawLower)) {
      score += 500;
    }

    // 5. Substring or alias matches
    if (score === 0 || score === 200) {
      let matched = false;
      if (tUpper.includes(normUpper) || tUpper.includes(rawUpper)) {
        score += 300;
        matched = true;
      }
      if (normName.includes(norm) || nNorm.includes(norm) || nNorm.includes(rawLower)) {
        score += 250;
        matched = true;
      }
      if (normAliases.includes(norm) || rawAliases.includes(rawLower)) {
        score += 180;
        matched = true;
      }
      if (sSector && sSector.includes(norm)) {
        score += 100;
        matched = true;
      }

      if (!matched) continue;
    }

    scoredMatches.push({ stock: s, score });
  }

  // Sort descending by relevance score
  scoredMatches.sort((a, b) => b.score - a.score);
  return scoredMatches.slice(0, limit).map((m) => m.stock);
}

/**
 * Quick lookup by ticker (case-insensitive, full-width normalized, .T suffix tolerant)
 */
const TICKER_MAP = new Map<string, UniverseStock>();
for (const s of ALL_UNIVERSE_STOCKS) {
  TICKER_MAP.set(s.ticker.toUpperCase(), s);
}

export function getUniverseStockByTicker(ticker: string): UniverseStock | undefined {
  if (!ticker) return undefined;
  const clean = normalizeSearchQuery(ticker)
    .replace(/^(?:TSE|TYO):/i, "")
    .replace(/\.T$/i, "")
    .toUpperCase();
  const found = TICKER_MAP.get(clean);
  if (found) return found;
  const rawClean = ticker
    .trim()
    .replace(/^(?:TSE|TYO):/i, "")
    .replace(/\.T$/i, "")
    .toUpperCase();
  return TICKER_MAP.get(rawClean);
}
